{"command": "cd /work
out=/tmp/inlined.dsl
: > "$out"
while IFS= read -r line; do
  trimmed=$(printf '%s' "$line" | sed 's/^[[:space:]]*//')
  case "$trimmed" in
    "!include"*)
      path=$(printf '%s' "$trimmed" | sed 's/^!include[[:space:]]*//')
      case "$path" in
        "!docs"*) : ;;
        *)
          if [ -f "$path" ]; then cat "$path" >> "$out"; echo "" >> "$out";
          else echo "MISSING INCLUDE: $path" >> "$out"; fi ;;
      esac
      ;;
    *) printf '%s\n' "$line" >> "$out" ;;
  esac
done < workspace.dsl
cat "$out""}

